mapper.select:
SELECT t.task_id, t.instance_id, t.node_id, t.candidate_type, t.candidate_id,
       t.handler_id, t.action, t.opinion, t.is_done, t.create_time, t.finish_time
FROM wf_task t
INNER JOIN wf_instance i ON t.instance_id = i.instance_id
INNER JOIN wf_process_definition d ON i.proc_def_id = d.proc_def_id

    AND t.is_done = 0
    AND t.candidate_id = #{personId}

        AND d.bus_type = #{query.busType}


        AND i.status = #{query.status}


        AND i.instance_id = #{query.instanceId}


        AND i.title LIKE CONCAT('%', #{query.instanceTitle}, '%')


ORDER BY t.create_time DESC

SELECT t.task_id, t.instance_id, t.node_id, t.candidate_type, t.candidate_id,
       t.handler_id, t.action, t.opinion, t.is_done, t.create_time, t.finish_time
FROM wf_task t
INNER JOIN wf_instance i ON t.instance_id = i.instance_id
INNER JOIN wf_process_definition d ON i.proc_def_id = d.proc_def_id

    AND t.is_done = 1
    AND t.handler_id = #{personId}

        AND d.bus_type = #{query.busType}


        AND i.status = #{query.status}


        AND i.instance_id = #{query.instanceId}


        AND i.title LIKE CONCAT('%', #{query.instanceTitle}, '%')


ORDER BY t.finish_time DESC
